/* Rotten Catfish 64 by AmruthGowda91200 — https://uiverse.io/AmruthGowda91200/rotten-catfish-64 */
.container {
  width: 100%;
  height: 100%;
  background: repeating-linear-gradient(
      -45deg,
      #ff7e5f,
      #ff7e5f 10px,
      #3f51b5 10px,
      #3f51b5 20px
    ),
    repeating-linear-gradient(
      45deg,
      #3f51b5,
      #3f51b5 10px,
      #ff7e5f 10px,
      #ff7e5f 20px
    ),
    repeating-linear-gradient(
      -30deg,
      #3f51b5,
      #3f51b5 10px,
      #ff7e5f 10px,
      #ff7e5f 20px
    ),
    repeating-linear-gradient(
      30deg,
      #ff7e5f,
      #ff7e5f 10px,
      #3f51b5 10px,
      #3f51b5 20px
    );
}
